package in.asmj.ride.web;
import in.asmj.ride.model.*;import in.asmj.ride.repo.*;import in.asmj.ride.service.CloudinaryUploadService;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;import org.springframework.web.multipart.MultipartFile;
@Controller public class SupportController {
 private final UserAccountRepository users;private final RideBookingRepository rides;private final SupportTicketRepository tickets;private final RideReviewRepository reviews;private final SafetyReportRepository safety;private final CloudinaryUploadService uploads;
 public SupportController(UserAccountRepository u,RideBookingRepository r,SupportTicketRepository t,RideReviewRepository v,SafetyReportRepository s,CloudinaryUploadService c){users=u;rides=r;tickets=t;reviews=v;safety=s;uploads=c;}
 private UserAccount me(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 @GetMapping("/support") public String support(Authentication a,Model m){UserAccount u=me(a);m.addAttribute("tickets","ADMIN".equals(u.getRole())?tickets.findAllByOrderByCreatedAtDesc():tickets.findByUserIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("rides",rides.findAll().stream().filter(r->u.getId().equals(r.getCustomerId())||u.getId().equals(r.getAssignedDriverId())).toList());m.addAttribute("admin","ADMIN".equals(u.getRole()));return "support";}
 @PostMapping("/support/create") public String create(Authentication a,@RequestParam(required=false)String rideId,@RequestParam String category,@RequestParam String subject,@RequestParam String message,@RequestParam(value="attachments",required=false)List<MultipartFile> attachments){UserAccount u=me(a);if(!List.of("GENERAL","PAYMENT","TRIP","DRIVER","SAFETY","LOST_ITEM","OTHER").contains(category)||subject.isBlank()||subject.length()>120||message.isBlank()||message.length()>2000)return "redirect:/support?error";if(rideId!=null&&!rideId.isBlank()){RideBooking r=rides.findById(rideId).orElse(null);if(r==null||(!u.getId().equals(r.getCustomerId())&&!u.getId().equals(r.getAssignedDriverId())))return "redirect:/support?error";}SupportTicket t=new SupportTicket();t.setUserId(u.getId());t.setUserName(u.getName());t.setRideId(rideId);t.setCategory(category);t.setSubject(subject.trim());t.setMessage(message.trim());try{t.setAttachments(uploadAttachments(attachments,"asmj-ride/support/"+u.getId(),"SUPPORT_ATTACHMENT"));tickets.save(t);return "redirect:/support?created";}catch(RuntimeException ex){return "redirect:/support?error=upload";}}
 @PostMapping("/admin/support/{id}/reply") public String reply(@PathVariable String id,@RequestParam String reply,@RequestParam String status){SupportTicket t=tickets.findById(id).orElseThrow();if(reply==null||reply.isBlank()||reply.length()>2000||!List.of("OPEN","IN_PROGRESS","RESOLVED","CLOSED").contains(status))return "redirect:/support?error";t.setAdminReply(reply.trim());t.setStatus(status);tickets.save(t);return "redirect:/support?updated";}
 @PostMapping("/rides/{id}/review") public String review(Authentication a,@PathVariable String id,@RequestParam(required=false,defaultValue="0")int rating,@RequestParam(required=false,defaultValue="0")int driverRating,@RequestParam(required=false)String comment){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!"COMPLETED".equals(r.getStatus())||(!u.getId().equals(r.getCustomerId())&&!u.getId().equals(r.getAssignedDriverId()))||rating<0||rating>5||driverRating<0||driverRating>5)return "redirect:/customer?reviewError";RideReview v=reviews.findByRideId(id).orElseGet(RideReview::new);v.setRideId(id);v.setCustomerId(r.getCustomerId());v.setDriverId(r.getAssignedDriverId());if(u.getId().equals(r.getCustomerId()))v.setCustomerRating(rating);else v.setDriverRating(driverRating);if(comment!=null&&comment.length()<=1000)v.setComment(comment.trim());reviews.save(v);return "redirect:/customer?reviewed";}
 @PostMapping("/rides/{id}/sos") public String sos(Authentication a,@PathVariable String id,@RequestParam(required=false)String details,@RequestParam(value="attachments",required=false)List<MultipartFile> attachments){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getCustomerId())&&!u.getId().equals(r.getAssignedDriverId()))return "redirect:/customer?error";SafetyReport s=new SafetyReport();s.setRideId(id);s.setUserId(u.getId());s.setUserName(u.getName());s.setType("SOS");s.setDetails(details==null||details.isBlank()?"Emergency assistance requested":details.substring(0,Math.min(1000,details.length())));try{s.setAttachments(uploadAttachments(attachments,"asmj-ride/safety-reports/"+u.getId(),"SAFETY_EVIDENCE"));safety.save(s);return "redirect:/support?sosSent";}catch(RuntimeException ex){return "redirect:/support?error=upload";}}
 @PostMapping("/rides/{id}/complaint") public String complaint(Authentication a,@PathVariable String id,@RequestParam String type,@RequestParam String details,@RequestParam(value="attachments",required=false)List<MultipartFile> attachments){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getCustomerId())&&!u.getId().equals(r.getAssignedDriverId())||details==null||details.isBlank()||details.length()>1500)return "redirect:/support?error";SafetyReport s=new SafetyReport();s.setRideId(id);s.setUserId(u.getId());s.setUserName(u.getName());s.setType(List.of("LOST_ITEM","SAFETY","FRAUD","OTHER").contains(type)?type:"OTHER");s.setDetails(details.trim());try{s.setAttachments(uploadAttachments(attachments,"asmj-ride/safety-reports/"+u.getId(),"SAFETY_EVIDENCE"));safety.save(s);return "redirect:/support?reported";}catch(RuntimeException ex){return "redirect:/support?error=upload";}}
 @PostMapping("/admin/safety/{id}") public String safetyUpdate(@PathVariable String id,@RequestParam String status,@RequestParam(required=false)String note){SafetyReport s=safety.findById(id).orElseThrow();if(!List.of("OPEN","IN_PROGRESS","RESOLVED","CLOSED").contains(status))return "redirect:/support?error";s.setStatus(status);s.setAdminNote(note);safety.save(s);return "redirect:/support?updated";}
    private List<UploadedAsset> uploadAttachments(List<MultipartFile> files,String folder,String category){List<UploadedAsset> result=new ArrayList<>();if(files==null)return result;try{for(MultipartFile f:files)if(f!=null&&!f.isEmpty()){if(result.size()>=5)throw new IllegalArgumentException("Maximum 5 attachments allowed.");result.add(uploads.upload(f,folder,category,true));}return result;}catch(RuntimeException ex){result.forEach(uploads::delete);throw ex;}}
}
